CREATE OR REPLACE FUNCTION public.financeiro_importar(p_linhas jsonb,p_confirmado boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SET search_path=public AS $$ DECLARE linha jsonb; result jsonb='[]'::jsonb; BEGIN IF NOT public.fin1_authorized(false) OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Importacao exclusiva de admin.' USING ERRCODE='42501'; END IF; IF NOT p_confirmado THEN RAISE EXCEPTION 'Confirme a previa antes de importar.'; END IF; IF jsonb_typeof(p_linhas)<>'array' OR jsonb_array_length(p_linhas)>5000 THEN RAISE EXCEPTION 'Importe ate 5000 linhas por lote.'; END IF; IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_linhas) x GROUP BY x->>'id_externo' HAVING count(*)>1) THEN RAISE EXCEPTION 'id_externo repetido dentro do arquivo.'; END IF; FOR linha IN SELECT value FROM jsonb_array_elements(p_linhas) LOOP IF NULLIF(linha->>'id_externo','') IS NULL THEN RAISE EXCEPTION 'id_externo obrigatorio na importacao.'; END IF; result=result||public.financeiro_operar('salvar',linha||jsonb_build_object('origem','importacao'),'{}','Importacao confirmada',true); END LOOP; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.financeiro_importar(jsonb,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.financeiro_importar(jsonb,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.financeiro_saldos_linhas(p_ids uuid[]) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF NOT public.fin1_authorized(true) THEN RAISE EXCEPTION 'Saldo corrido exclusivo de admin e diretor.' USING ERRCODE='42501'; END IF; IF cardinality(p_ids)>100 THEN RAISE EXCEPTION 'Leia no maximo 100 saldos por pagina.'; END IF;
 WITH running AS(SELECT m.id,c.saldo_inicial+sum(CASE WHEN m.tipo='entrada' THEN m.valor ELSE -m.valor END) OVER(PARTITION BY m.conta_id ORDER BY m.data_pagamento,m.created_at,m.id ROWS UNBOUNDED PRECEDING) AS saldo FROM public.financeiro_movimentacoes m JOIN public.financeiro_contas c ON c.id=m.conta_id WHERE m.status='realizado' AND m.data_pagamento>=c.data_saldo_inicial)
 SELECT COALESCE(jsonb_agg(to_jsonb(r)),'[]'::jsonb) INTO result FROM running r WHERE r.id=ANY(p_ids); RETURN result; END $$;
REVOKE ALL ON FUNCTION public.financeiro_saldos_linhas(uuid[]) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.financeiro_saldos_linhas(uuid[]) TO authenticated;